// Disk store used only when R2 is not configured (local dev). Keys are generated by us
// (`image/2026-10/<uuid>.jpg`); reject anything that could leave this folder.
import { mkdir, readFile, unlink, writeFile } from 'node:fs/promises';
import path from 'node:path';

const root = path.resolve(process.cwd(), '.local-uploads');

function safe(key: string) {
	if (!key || key.includes('..') || path.isAbsolute(key)) throw new Error('Bad storage key');
	const file = path.resolve(root, key);
	if (file !== root && !file.startsWith(root + path.sep)) throw new Error('Bad storage key');
	return file;
}

export async function putLocal(key: string, body: ArrayBuffer) {
	const file = safe(key);
	await mkdir(path.dirname(file), { recursive: true });
	await writeFile(file, Buffer.from(body));
}

export async function readLocal(key: string) {
	return readFile(safe(key));
}

export async function deleteLocal(key: string) {
	await unlink(safe(key)).catch(() => {});
}
